using AdForLinux.DirectoryServices;
using AdForLinux.DirectoryServices.Security.Core;
using Xunit;
using static AdForLinux.FunctionalTests.SecurityDescriptorFixtures;
using CoreAce = AdForLinux.DirectoryServices.Security.Core.Ace;

namespace AdForLinux.FunctionalTests;

/// <summary>Offline replay of literal Microsoft 9.0.0 Windows outputs. No directory fixtures.
/// Inputs and outputs were copied from docs/research/acl-windows-oracle/results/windows-net8.txt;
/// net10 recording has identical case bodies. Expectations are not generated by the engine.</summary>
public partial class AclMutationReplayTests
{
    private const SecurityMasks All = SecurityMasks.Owner | SecurityMasks.Group | SecurityMasks.Dacl | SecurityMasks.Sacl;

    [Theory]
    [MemberData(nameof(RecordedMutations))]
    public void Recorded_mutation_matches_bytes_and_return(string caseName, string input,
        int operationValue, byte[] rule, int sectionValue, string expected, bool returnValue)
    {
        Assert.False(string.IsNullOrEmpty(caseName));
        var operation = (AclModification)operationValue;
        var section = (SecurityMasks)sectionValue;
        var original = Convert.FromHexString(input);
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(original, All));
        var result = engine.Modify(section, operation, CoreAce.Read(rule));
        Assert.Equal(Convert.FromHexString(expected), result.Engine.Descriptor.GetBinaryForm());
        if (operation == AclModification.Remove) Assert.Equal(returnValue, result.ReturnValue);
        Assert.Equal(original, engine.Descriptor.GetBinaryForm());
        Assert.Equal(original, result.Engine.OriginalDescriptor.GetBinaryForm());
        Assert.Equal(SecurityMasks.None, engine.WriteIntent);
    }

