    [Theory]
    [MemberData(nameof(RecordedStateCalls))]
    public void Recorded_state_call_matches_bytes(string caseName, byte[] input, string call, string expected)
    {
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(input, All));
        var result = call switch
        {
            "owner" => engine.SetOwner(Sid.Parse("S-1-5-21-1-2-3-1001")),
            "group" => engine.SetGroup(Sid.Parse("S-1-5-21-1-2-3-1001")),
            "audit" => engine.Modify(SecurityMasks.Sacl, AclModification.Add, CoreAce.Read(Ace(2, 0x40, 0x10, U1))),
            "unprotect" => engine.SetProtection(SecurityMasks.Dacl, false, true),
            "protect" => engine.SetProtection(SecurityMasks.Dacl, true, false),
            "addEveryone" => engine.Modify(SecurityMasks.Dacl, AclModification.Add, CoreAce.Read(Ace(0, 3, uint.MaxValue, Everyone))),
            "addDeny" => engine.Modify(SecurityMasks.Dacl, AclModification.Add, CoreAce.Read(Ace(1, 0, 0x10, U1))),
            "set" => engine.Modify(SecurityMasks.Dacl, AclModification.Set, CoreAce.Read(Ace(0, 0, 0x10, U1))),
            "reset" => engine.Modify(SecurityMasks.Dacl, AclModification.Reset, CoreAce.Read(Ace(0, 0, 0x10, U1))),
            "removeNoMatch" => engine.Modify(SecurityMasks.Dacl, AclModification.Remove, CoreAce.Read(Ace(0, 0, 0x10, U2))),
            "specificNoMatch" => engine.Modify(SecurityMasks.Dacl, AclModification.RemoveSpecific, CoreAce.Read(Ace(0, 0, 0x10, U2))),
            "allNoMatch" => engine.Modify(SecurityMasks.Dacl, AclModification.RemoveAll, CoreAce.Read(Ace(0, 0, 0x10, U2))),
            "purgeNoMatch" => engine.Purge(SecurityMasks.Dacl, Sid.Parse("S-1-5-21-1-2-3-1002")),
            "purgeEveryone" => engine.Purge(SecurityMasks.Dacl, Sid.Parse("S-1-1-0")),
            "removePartial" => engine.Modify(SecurityMasks.Dacl, AclModification.Remove, CoreAce.Read(Ace(0, 0, 0x10, Everyone))),
            "specificEveryone" => engine.Modify(SecurityMasks.Dacl, AclModification.RemoveSpecific, CoreAce.Read(Ace(0, 3, uint.MaxValue, Everyone))),
            "purgeU1" => engine.Purge(SecurityMasks.Dacl, Sid.Parse("S-1-5-21-1-2-3-1001")),
            _ => throw new ArgumentException(caseName),
        };
        Assert.Equal(Convert.FromHexString(expected), result.Engine.Descriptor.GetBinaryForm());
        Assert.Equal(input, engine.Descriptor.GetBinaryForm());
        Assert.Equal(input, result.Engine.OriginalDescriptor.GetBinaryForm());
    }

