        yield return new object[] { "B6 empty DACL: RemoveAccess(U2, Allow) [no match]", Build(Admins, Admins, Acl(4)), "allNoMatch", "010004801400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000" };
        yield return new object[] { "B6 empty DACL: PurgeAccessRules(U2) [no match]", Build(Admins, Admins, Acl(4)), "purgeNoMatch", "010004801400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000" };
        yield return new object[] { "B6 empty DACL: PurgeAccessRules(Everyone)", Build(Admins, Admins, Acl(4)), "purgeEveryone", "010004801400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000" };
        yield return new object[] { "B6 empty DACL: RemoveAccessRule(allow Everyone RP) [partial]", Build(Admins, Admins, Acl(4)), "removePartial", "010004801400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000" };
        yield return new object[] { "B6 empty DACL: RemoveAccessRuleSpecific(Everyone 0xFFFFFFFF CI|OI) [exact]", Build(Admins, Admins, Acl(4)), "specificEveryone", "010004801400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000" };
        yield return new object[] { "F1 PurgeAccessRules(U1)", Convert.FromHexString(""), "purgeU1", "0100048014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004005000020000000000240010000000010500000000000515000000010000000200000003000000EA0300000010240010000000010500000000000515000000010000000200000003000000E9030000" };
    }

    [Theory]
    [MemberData(nameof(RecordedAuditMerges))]
    public void Recorded_audit_merge_matches_bytes(byte flags, uint mask, string expected)
    {
        var input = Build(Admins, Admins, Acl(4), sacl: Acl(4, Ace(2, 0x40, 0x10, U1)));
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(input, All));
        var result = engine.Modify(SecurityMasks.Sacl, AclModification.Add, CoreAce.Read(Ace(2, flags, mask, U1)));
        Assert.Equal(Convert.FromHexString(expected), result.Engine.Descriptor.GetBinaryForm());
        Assert.Equal(input, engine.Descriptor.GetBinaryForm());
    }

