    [Theory]
    [MemberData(nameof(RecordedNoncanonicalInputs))]
    public void Recorded_noncanonical_add_and_purge_refuse_atomically(string caseName, string input)
    {
        Assert.False(string.IsNullOrEmpty(caseName));
        var bytes = Convert.FromHexString(input);
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(bytes, All));
        Assert.Throws<InvalidOperationException>(() => engine.Modify(SecurityMasks.Dacl,
            AclModification.Add, CoreAce.Read(Ace(0, 0, 0x20, U2))));
        Assert.Throws<InvalidOperationException>(() => engine.Purge(SecurityMasks.Dacl,
            Sid.Parse("S-1-5-21-1-2-3-1002")));
        Assert.Equal(bytes, engine.Descriptor.GetBinaryForm());
        Assert.Equal(SecurityMasks.None, engine.WriteIntent);
    }

    public static IEnumerable<object[]> RecordedNoncanonicalInputs()
    {
        yield return new object[] { "G1 explicit allow before explicit deny: import", "0100048014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004005000020000000000240010000000010500000000000515000000010000000200000003000000E90300000100240010000000010500000000000515000000010000000200000003000000EA030000" };
        yield return new object[] { "G1 inherited before explicit: import", "0100048014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004005000020000000010240010000000010500000000000515000000010000000200000003000000E90300000000240020000000010500000000000515000000010000000200000003000000EA030000" };
    }

    [Theory]
    [InlineData("absent")]
    [InlineData("NULL")]
    [InlineData("empty")]
    [InlineData("populated")]
    public void Recorded_B4_protection_preserve_inheritance(string state)
    {
        var input = state switch
        {
            "absent" => Build(Admins, Admins, null),
            "NULL" => Build(Admins, Admins, null, nullDacl: true),
            "empty" => Build(Admins, Admins, Acl(4)),
            _ => Build(Admins, Admins, Acl(4, Ace(0, 0, 0x10, Everyone))),
        };
        var expected = state switch
        {
            "absent" => "0100049014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004001C000100000000031400FFFFFFFF010100000000000100000000",
            "NULL" => "0100049014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004001C000100000000031400FFFFFFFF010100000000000100000000",
            "empty" => "010004901400000024000000000000003400000001020000000000052000000020020000010200000000000520000000200200000400080000000000",
            "populated" => "0100049014000000240000000000000034000000010200000000000520000000200200000102000000000005200000002002000004001C00010000000000140010000000010100000000000100000000",
            _ => throw new ArgumentException(nameof(state)),
        };
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(input, All));
        var result = engine.SetProtection(SecurityMasks.Dacl, true, true);
        Assert.Equal(Convert.FromHexString(expected), result.Engine.Descriptor.GetBinaryForm());
        Assert.Equal(input, engine.Descriptor.GetBinaryForm());
    }

    [Fact]
    public void Recorded_D1_explicit_rule_sequence()
    {
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(Build(Admins, Admins, Acl(4)), All));
        foreach (var rule in new[]
        {
            Ace(0, 0, 0x10, U1), Ace(1, 0, 0x10, U2),
            ObjAce(5, 0, 0x10, 1, G1, null, U2),
            ObjAce(6, 0, 0x20, 1, G1, null, U1), Ace(0, 2, 4, U2),
        }) engine = engine.Modify(SecurityMasks.Dacl, AclModification.Add, CoreAce.Read(rule)).Engine;
        Assert.Equal(Convert.FromHexString(""), engine.Descriptor.GetBinaryForm());
    }

    [Fact]
    public void Recorded_D2_explicit_add_preserves_inherited_order()
    {
        var input = Convert.FromHexString("01000480140000002400000000000000340000000102000000000005200000002002000001020000000000052000000020020000040040000200000000121400100000000101000000000001000000000110240020000000010500000000000515000000010000000200000003000000EA030000");
        var engine = new AclMutationEngine(SecurityDescriptor.Parse(input, All));
        engine = engine.Modify(SecurityMasks.Dacl, AclModification.Add, CoreAce.Read(Ace(0, 0, 0x10, U1))).Engine;
        engine = engine.Modify(SecurityMasks.Dacl, AclModification.Add, CoreAce.Read(Ace(1, 0, 0x20, U1))).Engine;
        Assert.Equal(Convert.FromHexString(""), engine.Descriptor.GetBinaryForm());
    }

